// Suggested next questions under the latest answer, for clients who are not sure what to ask next.
// Fixed lists by topic (not generated by the model), so every suggestion is something the assistant can actually answer
// or route without raising a ticket. Order matters: the first topic whose words match the question wins.
// Personal ones ("my review", "my card") are only offered when signed in. At most three, never one already asked.
// 2a: after a loan, investment, property or large-transfer answer a signed-in client is also offered a meeting request
// (MEETING_CHIP); when the reply carries care (guardrail.CARE) she is offered a person instead of any product or meeting chip.
export const MEETING_CHIP='Request a meeting with your RM';
export const CARE_CHIP='Talk to a person';
const TOPICS=[
  // Her existing requests (status, references, a list of them): request chips, never meeting ones. A meeting request stays a meeting.
  {key:'requests',match:/^(?![^]*\bmeeting)[^]*(?:\bTCK-\d+|\b(?:my|the|that|this)\s+(?:\w+\s+)?(?:requests?|tickets?|cases?)\b|\brequests? that could match\b|\byour (?:open |latest )?(?:\d+ )?requests\b)/i,ask:[
    ['What is the status of my request?',true],['Show my open requests',true],['Can I cancel my request?',true]]},
  {key:'fraud',match:/\b(?:unrecogni[sz]ed|don'?t recogni[sz]e|suspicious|fraud|stolen|lost (?:my )?card|block(?:ed)? (?:my )?card|london charges?|(?:someone|somebody) (?:has )?used my card|used my card without permission)\b/i,ask:[
    ['What happens after I report a charge?',false],['Will I get my money back?',false],['How do I get a replacement card?',false]]},
  {key:'document',match:/\b(?:upload|proof of address|utility bill|document|declaration|tax residency|not accepted|rejected|correction)\b/i,ask:[
    ['What does a proof of address need to show?',false],['What do I still need to send for my review?',true],['How do I answer the bank\'s question?',true]]},
  {key:'compliance',match:/\b(?:review|compliance|kyc|due date|deadline|the bank asked)\b/i,ask:[
    ['What do I still need to send for my review?',true],['When is my review due?',true],['How do I answer the bank\'s question?',true]]},
  {key:'statements',match:/\bstatements?\b/i,ask:[
    ['How do I get an older or certified statement?',false],['What is my account balance?',true],['Show my recent transactions',true]]},
  {key:'meeting',match:/\b(?:meet|meeting|appointment|book(?:ing)?|schedule)\b/i,ask:[
    ['Who is my relationship manager?',true],['What should I prepare for the meeting?',true],['What is the status of my request?',true]]},
  {key:'relationship',match:/\b(?:relationship manager|my rm|advis[eo]r|banker)\b/i,ask:[
    ['Request a meeting with your RM',true],['What should I prepare for the meeting?',true],['What can you help me with?',false]]},
  {key:'details',match:/\b(?:(?:my|new|home|mailing) address|phone number|mobile number|email address|personal details|change my name)\b/i,ask:[
    ['What does a proof of address need to show?',false],['What is the status of my request?',true],['What can you help me with?',false]]},
  {key:'large_transfer',match:/\b(?:large|big|significant|substantial|complex|cross[- ]border)\b[^.?!]{0,30}\b(?:transfers?|wires?|remittances?)\b|\b(?:transfer\w*|send\w*|wir\w+|mov\w+)\b[^.?!]{0,30}(?:\d{1,3}(?:,\d{3}){1,}|\b\d{5,}|\b\d+\s?k\b|\bmillion\b)/i,ask:[
    ['How long do overseas transfers usually take?',false],['What are the fees for overseas transfers?',false]]},
  {key:'transfer',match:/\b(?:transfer|pending|payment (?:failed|declined)|declined|went through)\b/i,ask:[
    ['What if it is still pending tomorrow?',false],['How long do transfers usually take?',false],['Show my recent transactions',true]]},
  {key:'limit',match:/\blimit\b/i,ask:[
    ['What documents do I need for a higher limit?',false],['What is the status of my request?',true],['When is my card payment due?',true]]},
  {key:'loans',match:/\b(?:loans?|mortgages?|borrow\w*|refinanc\w*|property|condo|hdb|house)\b/i,ask:[
    ['Which financing do you offer?',false],['How is property financing arranged?',false],['Can I borrow against my investments?',true]]},
  {key:'investments',match:/\b(?:invest\w*|unit trusts?|funds?|portfolio|stocks?|shares|bonds?|wealth|retirement)\b/i,ask:[
    ['What is a unit trust?',false],['What are the risks of investing?',false]]},
  {key:'cards',match:/\b(?:card|credit|minimum payment|interest|annual fee)\b/i,ask:[
    ['When is my card payment due?',true],['Does paying only the minimum avoid interest?',false],['Can I increase my credit limit?',true]]},
  {key:'accounts',match:/\b(?:accounts?|balances?|savings?|fees?|charges?|deposits?|withdraw\w*|spen[dt]\w*|transactions?|matur\w*|income|money)\b/i,ask:[
    ['What is my account balance?',true],['Show my recent transactions',true],['Are there fees on my savings account?',true]]},
];
const DOMAIN={fraud:'fraud',compliance:'compliance',document:'document',relationship:'meeting'};
const MEETING_TOPICS=new Set(['loans','investments','large_transfer']);
const HANDED_OVER=[['What is the status of my request?',true],[MEETING_CHIP,true],['What else can you help me with?',false]];
const GENERAL=[['What is my account balance?',true],['What do I still need to send for my review?',true],['What can you help me with?',false]];

export function topicOf(question,message) {
  const found=TOPICS.find(topic=>topic.match.test(question||''));
  if(found)return found.key;
  const domain=(message?.sections||[]).map(section=>DOMAIN[section.domain]).find(Boolean);
  if(domain)return domain;
  return TOPICS.find(topic=>topic.match.test(message?.content||''))?.key||null;
}

// The fraud charge list (CR12; saved chats from before 2b only) asks for a plain yes; offer it as a one-tap reply instead of other suggestions.
export const CONFIRM_REPORT='Yes, report it';
export function followUps({question,message,signedIn,asked=[]}) {
  if(!message||message.role!=='assistant'||!message.content)return [];
  if(message.offer)return [];  // the offer block has its own Confirm and Cancel (v5)
  // A charge list to confirm keeps its button even when another part of the reply was withheld (CR12).
  if(signedIn&&message.content.includes(`“${CONFIRM_REPORT}”`))return [CONFIRM_REPORT];
  if(message.error||message.response_origin==='validation'||message.source_check==='rejected')return [];
  // CR12: the lost-card offer asks before reporting (saved chats from before 2b only).
  if(signedIn&&message.content.includes('Reply “Yes, report my card”'))return ['Yes, report my card','No'];
  // CR8: a handover preview offers its choices as one tap each; nothing is sent until she picks one.
  if(signedIn&&message.content.includes('Here’s what I’d send to your relationship manager:')) {
    const offered=/“Add to (TCK-\d{6,})”/.exec(message.content);
    return offered?[`Add to ${offered[1]}`,'Open a new request','Cancel']:['Send to my RM','Cancel'];
  }
  // 2a: free times listed for a meeting request offer one tap each; her tap is her preferred time and the reply drafts the
  // request (with its own Confirm and Cancel). Nothing is held or booked from the chat.
  if(signedIn&&message.content.includes('Tell me which times suit you')) {
    const times=[...message.content.matchAll(/• ((?:Mon|Tue|Wed|Thu|Fri|Sat|Sun) \d{1,2} [A-Z][a-z]{2}, \d{1,2}:\d{2} (?:am|pm))/g)].map(match=>match[1]);
    // One button for every time listed (the reply lists at most six), so the text and the buttons always match.
    if(times.length)return times.slice(0,6);
  }
  // CR11: the active card-limit intake asks for a card without restarting the request.
  if(signedIn&&/\bWhich card is this for:/.test(message.content)) {
    const cards=[...message.content.matchAll(/(?:Signature|Travel) Card ending \d{4}/g)].map(match=>match[0]);
    if(cards.length>1)return cards.slice(0,3);
  }
  // "Which card's ... do you mean: your Signature Card ending 7310 or your Travel Card ending 5592?" → one tap per card.
  if(signedIn&&/^Which card['’]s .+ do you mean:/.test(message.content)) {
    const cards=[...message.content.matchAll(/your ([A-Z][A-Za-z ]{1,40}?) ending (\d{4})/g)].map(match=>`${match[1]} ending ${match[2]}`);
    if(cards.length>1)return [...cards.slice(0,3),'Both cards'].slice(0,4);
  }
  // Several requests could match: one tap per reference, so she picks without typing it.
  if(signedIn&&/Which reference do you mean\?/.test(message.content)) {
    const refs=[...new Set([...message.content.matchAll(/\bTCK-\d{6,}\b/g)].map(match=>match[0]))];
    if(refs.length>1)return refs.slice(0,5).map(ref=>`What is the status of ${ref}?`);
  }
  const seen=new Set([question,...asked].map(text=>String(text||'').trim().toLowerCase()));
  // 2a: care first (job loss, debt, bereavement, illness, pressure about money): a person, never a product or a meeting.
  if(message.care)return seen.has(CARE_CHIP.toLowerCase())?[]:[CARE_CHIP];
  // Several questions in one message: one suggestion for each part, in the order of the parts, so each stays on its topic.
  const parts=message.sections?.length>1?message.sections:null;
  if(parts&&!message.needs_human) {
    const picked=[];
    for(const section of parts) {
      const key=topicOf('',{sections:[section],content:section.answer});
      const pool=TOPICS.find(entry=>entry.key===key)?.ask||[];
      const chip=pool.find(([text,personal])=>(signedIn||!personal)&&!seen.has(text.toLowerCase())&&!picked.includes(text));
      if(chip)picked.push(chip[0]);
    }
    if(picked.length)return picked.slice(0,3);
  }
  const topic=topicOf(question,message);
  const pool=message.needs_human?HANDED_OVER:(TOPICS.find(entry=>entry.key===topic)?.ask||GENERAL);
  const chips=pool.filter(([text,personal])=>(signedIn||!personal)&&!seen.has(text.toLowerCase())).map(([text])=>text);
  if(signedIn&&!message.needs_human&&MEETING_TOPICS.has(topic)&&!seen.has(MEETING_CHIP.toLowerCase()))return [...chips.slice(0,2),MEETING_CHIP];
  return chips.slice(0,3);
}
